function loadFetch(file, tracker, fileSize, raw) {
    var p_file = file;

    tracker[file] = {
        total: fileSize || 0,
        loaded: 0,
        done: false,
    };

    return fetch(file).then(function (response) {
        if (!response.ok) {
            return Promise.reject(new Error(`Failed loading file '${file}'`));
        }

        const tr = getTrackedResponse(response, tracker[p_file]);
        return tr.arrayBuffer().then(function (buffer) {
            const bytes = new Uint8Array(buffer);
            const packed = bytes.length > 2 &&
                ((bytes[0] === 0x1f && bytes[1] === 0x8b) ||
                 (bytes[0] === 0x78 && (bytes[1] === 0x01 || bytes[1] === 0x5e || bytes[1] === 0x9c || bytes[1] === 0xda)));
            const data = (packed && typeof pako !== 'undefined') ? pako.inflate(bytes) : bytes;
            return new Response(data, { headers: tr.headers });
        });
    });
}

